INSERT INTO public.transport_hubs (id, legacy_id, name_en, name, category, category_label, location, upazila, description, connected_routes, facilities, operating_hours, phone_number, phone_numbers, banner_image, created_at) VALUES
  ('333ab7da-38dc-51fd-bdcc-6cb28c251f37', 'sherpur-bus-stand', 'Sherpur Bus Stand', 'শেরপুর বাস স্ট্যান্ড', 'bus_terminal', 'উপজেলা বাস টার্মিনাল', 'Sherpur Town, Dhaka–Bogura Highway, Sherpur, Bogura 5840', 'শেরপুর', 'Southern sub-district transit hub on the main Dhaka–Bogura highway. Major halt point for buses and travelers commuting between Bogura, Sirajganj, and Dhaka.', '["Bogura – Sherpur – Dhaka Highway","Sherpur – Dhunat Road","Sherpur – Chandaikona (Sirajganj)"]'::jsonb, '["Bus ticket counters for all major Dhaka-bound fleets","Food Village Ltd. highway mega rest stop nearby","Local transport & auto stand to Dhunat and rural unions","Emergency ambulance and repair services"]'::jsonb, '24/7', '+880 1938-896474', '["+880 1938-896474","+880 1712-568356","+880 1761-545967","+880 51-88055"]'::jsonb, 'https://images.unsplash.com/photo-1570125909232-eb263c188f7e?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('7195d6aa-2f0d-57ea-8a8c-5f47f9c3ad99', 'matidali-biman-mor', 'Matidali Biman Mor & Bus Stand', 'মাটিডালী বিমান মোড় ও বাস স্ট্যান্ড', 'highway_junction', 'উত্তর প্রবেশদ্বার ও হাইওয়ে টার্মিনাল', 'Matidali, Rangpur Road, Northern Entrance of Bogura City, Bogura 5800', 'বগুড়া সদর', 'The landmark northern crossroads of Bogura, featuring the iconic fighter aircraft sculpture. All northbound buses heading to Rangpur, Dinajpur, Gaibandha, and tourist spots like Mahasthangarh pass through here.', '["Bogura – Mahasthangarh – Shibganj","Bogura – Gobindaganj – Rangpur – Dinajpur","Bogura – Sonatola – Gaibandha","Bogra City Bypass Northern Junction"]'::jsonb, '["Northbound bus passenger shelters","Mahasthangarh & tourist transit CNG stand","Highway petrol pumps & workshops","Local fruit and sweet markets","Motel Castle MH proximity"]'::jsonb, '24/7', '+880 1829-440044', '["+880 1829-440044","+880 1715-176912","+880 1712-503068"]'::jsonb, 'https://images.unsplash.com/photo-1506521781263-d8422e82f27a?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('762a14d1-20d3-5e5d-9abe-c5ff2bbb66a5', 'bogura-railway-station', 'Bogura Railway Station', 'বগুড়া রেলওয়ে স্টেশন', 'railway_station', 'রেলওয়ে স্টেশন', 'Station Road, Satmatha (Near Fateh Ali Bazar), Bogura Sadar, Bogura 5800', 'বগুড়া সদর', 'Historic central railway station serving Bogura city. Connects Dhaka via Jamuna Bridge Link, and links northern destinations including Rangpur, Lalmonirhat, Kurigram, and Burimari via Santahar junction.', '["Bogura – Dhaka (Kamalapur / Airport)","Bogura – Santahar Junction","Bogura – Gaibandha – Rangpur","Bogura – Lalmonirhat – Burimari","Bogura – Kurigram"]'::jsonb, '["Ticket reservation counters (standard & online Shohoz validation)","1st class & general passenger waiting rooms","Railway police (GRP) station","Parcel & freight cargo booking office","Tea & food stalls, book stalls","Covered platform footbridge"]'::jsonb, 'Open 24 hours (aligned with scheduled train arrivals)', '+880 51-65042', '["+880 51-65042","+880 51-75042","+880 51-65082","131"]'::jsonb, 'https://images.unsplash.com/photo-1474487548417-781cb71495f3?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('89e07d5d-871d-5118-978f-27d7861a9f1e', 'mokamtola-bus-stand', 'Mokamtola Bus Stand', 'মোকামতলা হাইওয়ে বাস স্ট্যান্ড', 'bus_terminal', 'মহাসড়ক ট্রানজিট স্ট্যান্ড', 'Mokamtola, Dhaka–Rangpur Highway, Shibganj, Bogura 5810', 'শিবগঞ্জ', 'A vital transit junction located on the Dhaka–Rangpur highway in northern Bogura. Serves as the gateway for travelers to Sonatola, Joypurhat, and northern border corridors.', '["Dhaka–Bogura–Rangpur 4-Lane Highway","Mokamtola – Sonatola","Mokamtola – Shibganj – Joypurhat"]'::jsonb, '["Intercity bus highway stops","SR Travels, Shyamoli, Hanif highway ticket counters","Highway fruit stalls & food centers","Local auto & CNG terminal"]'::jsonb, '24/7', '+880 1991-177435', '["+880 1991-177435","+880 1711-394800","+880 1938-896483"]'::jsonb, 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('8bd4304a-6dd9-5b4e-819b-6ff6178d23f4', 'thanthania-bus-terminal', 'Thanthania Bus Terminal', 'ঠনঠনিয়া বাস টার্মিনাল / স্ট্যান্ড', 'bus_terminal', 'ভিআইপি ও দূরপাল্লার কোচ টার্মিনাল', 'Thanthania, Sherpur Road, Bogura Sadar, Bogura 5800', 'বগুড়া সদর', 'Bogura''s primary terminal for premium AC and non-AC intercity luxury coaches heading towards Dhaka, Chattogram, Sylhet, and Cox''s Bazar. Flagship counters of Shah Fateh Ali, Shyamoli, Hanif, SR Travels, and TR Travels operate here.', '["Bogura – Dhaka (Mohakhali, Gabtoli, Abdullahpur, Sayedabad)","Bogura – Chattogram – Cox''s Bazar","Bogura – Sylhet – Moulvibazar","Bogura – Cumilla – Feni – Noakhali"]'::jsonb, '["Air-conditioned VIP passenger waiting rooms","Online ticket print & digital booking desks","Luggage storage & parcel delivery services","Snack stalls, tea stalls & pharmacy","Dedicated taxi & auto pickup points"]'::jsonb, '24/7 (first morning departure 5:30 AM – late night sleeper coaches)', '+880 1938-896457', '["+880 1938-896457","+880 1711-020626","+880 1773-333766","+880 51-67111","+880 51-64455"]'::jsonb, 'https://images.unsplash.com/photo-1570125909232-eb263c188f7e?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('a708753d-59ea-575a-ab06-f99f7dac7ad0', 'santahar-railway-junction', 'Santahar Railway Junction', 'সান্তাহার রেলওয়ে জংশন', 'railway_junction', 'প্রধান রেলওয়ে জংশন', 'Santahar Pouroshava, Adamdighi Upazila, Bogura 5850', 'আদমদীঘি', 'One of the most historic and largest dual-gauge railway junctions in Bangladesh. Situated in Bogura district, Santahar connects the broad-gauge western line (Khulna–Rajshahi–Parbatipur–Chilahati) with the eastern meter/dual gauge line leading to Bogura Sadar and Dhaka.', '["Santahar – Bogura – Dhaka","Santahar – Parbatipur – Chilahati – Panchagarh","Santahar – Natore – Ishwardi – Khulna","Santahar – Rajshahi","Santahar – Lalmonirhat – Burimari"]'::jsonb, '["5 large covered railway platforms with dual-gauge track","Multiple computerized ticket booking & e-ticket counters","Railway Hospital & medical emergency unit","Running staff rest house & VIP retiring rooms","Railway Police (GRP) station & security camp","Major locomotive fueling & maintenance yard","24/7 canteens, tea stalls & market"]'::jsonb, 'Open 24 hours (trains operating day and night)', '+880 1737-580578', '["+880 1737-580578","+880 741-62222","+880 741-62233","131"]'::jsonb, 'https://images.unsplash.com/photo-1541427468627-a89a96e5ca1d?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('acf4b3b2-5810-5164-ac00-bee39ce86c3d', 'charmatha-central-bus-terminal', 'Charmatha Central Bus Terminal', 'চারমাথা কেন্দ্রীয় বাস টার্মিনাল', 'central_bus_terminal', 'প্রধান আন্তঃজেলা বাস টার্মিনাল', 'Charmatha, Santahar Road, Bogura Sadar, Bogura 5800', 'বগুড়া সদর', 'The largest and busiest road transport hub in Bogura district and North Bengal. Connects inter-district routes to Rangpur, Dinajpur, Rajshahi, Naogaon, Joypurhat, and Natore with 24/7 departures.', '["Bogura – Dhaka (via Bangabandhu Bridge)","Bogura – Rangpur – Dinajpur","Bogura – Rajshahi – Chapainawabganj","Bogura – Naogaon – Joypurhat","Bogura – Pabna – Kushtia – Khulna"]'::jsonb, '["24-hour bus departure & arrival bays","Multiple operator ticket booking counters","Passenger waiting lounge & washrooms","Highway police outpost & security check","Mosque & prayer area","On-site hotels, motels & 24/7 food restaurants","CNG auto-rickshaw & electric rickshaw stands"]'::jsonb, '24/7 (round the clock)', '+880 1733-041720', '["+880 1733-041720","+880 1819-934372","+880 1938-805345","+880 51-66087"]'::jsonb, 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('c2ada42a-29d3-5679-ba5b-2e0379479fac', 'satmatha-zero-point', 'Satmatha Zero Point Transit Hub', 'সাতমাথা জিরো পয়েন্ট', 'highway_junction', 'শহরের প্রাণকেন্দ্র ও লোকাল ট্রান্সপোর্ট হাব', 'Satmatha, Bogura City Centre, Bogura 5800', 'বগুড়া সদর', 'The pulsating geographical heart of Bogura where seven arterial roads converge. Houses major bus ticket booking corporate offices, auto-rickshaws, bike rentals, and direct access to government offices and market hubs.', '["Sherpur Road (to Thanthania, Banani, Dhaka)","Rangpur Road (to Matidali, Mahasthangarh)","Santahar Road (to Charmatha, Rail Station)","Nawabbari Road (to Runner Plaza, Karatoa river)","Park Road (to Pouro Park, Judge Court)"]'::jsonb, '["Head booking offices of major luxury bus lines","Town easybike and auto-rickshaw central stands","Traffic police headquarters and help desk","ATM booths, exchange & top retail centers","Bogura Doi, sweetmeat and dining hubs"]'::jsonb, '24/7 (peak activity 6:00 AM – 11:30 PM)', '+880 1938-896456', '["+880 1938-896456","+880 1712-900117","+880 1971-184895","+880 51-61222","+880 51-64920"]'::jsonb, 'https://images.unsplash.com/photo-1477959858617-67f30bc75b82?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('e63250bb-88cc-5f14-ae71-0929df9a9bb1', 'banani-highway-junction', 'Banani Highway Junction & Stand', 'বনানী মোড় ও হাইওয়ে বাস স্ট্যান্ড', 'highway_junction', 'মহাসড়ক জংশন ও বাস স্ট্যান্ড', 'Banani, Dhaka–Bogura Highway & Bypass Intersection, Bogura 5800', 'বগুড়া সদর / শাজাহানপুর', 'The southern gateway to Bogura city where the Dhaka–Rangpur national highway intersects the Bogura town bypass. High-frequency stop for all passing intercity coaches, highway motels, and local transport.', '["Bogura City – Dhaka Highway","Bogura Bypass – Rangpur Road","Bogura – Natore – Pabna","Bogura – Sirajganj"]'::jsonb, '["Highway coach passenger pickup counters","SR Travels, TR Travels, Agomony Express counters","Highway filling stations & EV fast chargers","Ambulance & 24/7 vehicle breakdown towing support","Hotel Siesta & Parjatan Motel proximity"]'::jsonb, '24/7', '+880 1726-557929', '["+880 1726-557929","+880 1991-177432","+880 51-65333","+880 51-51262"]'::jsonb, 'https://images.unsplash.com/photo-1519003722824-194d4455a60c?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('fce441e9-8e58-5ca7-8b6c-ef873e638a31', 'dupchanchia-bus-stand', 'Dupchanchia Bus Stand', 'দুপচাঁচিয়া বাস স্ট্যান্ড', 'bus_terminal', 'উপজেলা বাস টার্মিনাল', 'Bogura–Naogaon Highway, Dupchanchia, Bogura 5880', 'দুপচাঁচিয়া', 'Key western transit terminal connecting Bogura Sadar with Naogaon district and Joypurhat. Facilitates seamless agricultural and passenger traffic between western upazilas and the district headquarters.', '["Bogura – Dupchanchia – Naogaon","Dupchanchia – Akkelpur – Joypurhat","Dupchanchia – Talora Railway Station"]'::jsonb, '["Direct bus counters for Dhaka and Naogaon routes","Local electric three-wheeler and microbus stand","Market and commercial shopping centers"]'::jsonb, '5:30 AM – 10:30 PM', '+880 1938-896472', '["+880 1938-896472","+880 1711-411355","+880 1718-071455"]'::jsonb, 'https://images.unsplash.com/photo-1519003722824-194d4455a60c?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z')
INSERT INTO public.transport_services (id, legacy_id, operator_name_en, operator_name, service_type_en, service_type, headquarters, online_booking_url, description, facilities, major_routes, counters, phone_number, phone_numbers, banner_image, created_at) VALUES
  ('03153be6-6a61-5faf-b76c-7e82546c88f6', 'karatoa-express', 'Karatoa Express (Train 713 / 714)', 'করতোয়া এক্সপ্রেস (৭১৩ / ৭১৪)', 'intercity_train', 'আঞ্চলিক আন্তঃনগর এক্সপ্রেস ট্রেন', 'Bangladesh Railway (West Zone)', 'https://eticket.railway.gov.bd/', 'Dedicated regional express connecting Santahar Junction and Bogura with Burimari border station. Named after Bogura''s historic Karatoa river, it is a vital lifeline for daily commuters and travelers in northern Bogura.', '["Shovon Chair & Shovon coaches","Morning departure from Santahar & Bogura","Affordable civic rail travel linking northern sub-districts"]'::jsonb, '["Santahar – Bogura – Sonatola – Bonarpara – Gaibandha – Kaunia – Lalmonirhat – Burimari"]'::jsonb, '[{"location":"Bogura","counter_name":"Bogura Station Master Office","phone_numbers":["051-65042"]}]'::jsonb, '+880 51-65042', '["+880 51-65042","+880 1737-580578","131"]'::jsonb, 'https://images.unsplash.com/photo-1506521781263-d8422e82f27a?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('1e169af5-d0f5-5aaa-b20f-22ccd9322f4c', 'rangpur-express', 'Rangpur Express (Train 771 / 772)', 'রংপুর এক্সপ্রেস (৭৭১ / ৭৭২)', 'intercity_train', 'আন্তঃনগর এক্সপ্রেস ট্রেন (বাংলাদেশ রেলওয়ে)', 'Bangladesh Railway (West Zone)', 'https://eticket.railway.gov.bd/', 'Daily intercity express train connecting Rangpur divisional city with the capital Dhaka, with scheduled stops at Bogura Railway Station and Santahar Junction.', '["AC Cabin / Berths (first class)","Snigdha AC Chair coaches","Shovon Chair coaches","Catering service & security patrol"]'::jsonb, '["Dhaka – Airport – Bogura – Gaibandha – Pirgachha – Kaunia – Rangpur"]'::jsonb, '[{"location":"Bogura Station Road","counter_name":"Bogura Railway Station","phone_numbers":["051-65042"]},{"location":"Adamdighi, Bogura","counter_name":"Santahar Junction","phone_numbers":["01737-580578"]}]'::jsonb, '131', '["131","+880 51-65042","+880 1737-580578"]'::jsonb, 'https://images.unsplash.com/photo-1541427468627-a89a96e5ca1d?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('398e673c-e0d9-5321-8fe0-a21de8435c14', 'hanif-enterprise', 'Hanif Enterprise', 'হানিফ এন্টারপ্রাইজ', 'intercity_bus', 'জাতীয় আন্তঃজেলা বাস সার্ভিস', 'Dhaka / Satmatha, Bogura', 'https://www.shohoz.com/bus-tickets', 'The largest fleet operator in Bangladesh. Connects Bogura with almost every divisional city and district headquarters across the country with round-the-clock departures.', '["Both luxury 1x2 AC and budget-friendly 2x2 executive Non-AC buses","24/7 continuous departures","Extensive counter network across all major Bogura intersections","Luggage carriage & parcel express network"]'::jsonb, '["Bogura – Dhaka (Gabtoli / Mohakhali)","Bogura – Chattogram","Bogura – Cox''s Bazar","Bogura – Sylhet – Barishal"]'::jsonb, '[{"location":"Satani Mega Center, Sherpur Road, Satmatha, Bogura","counter_name":"Satmatha Counter","phone_numbers":["01932-657916"]},{"location":"Charmatha Central Bus Terminal, Bogura","counter_name":"Charmatha Counter","phone_numbers":["01713-402650"]}]'::jsonb, '+880 1932-657916', '["+880 1932-657916","+880 1713-402650","+880 1713-402655"]'::jsonb, 'https://images.unsplash.com/photo-1519003722824-194d4455a60c?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('6db5dbe1-b133-5489-a51f-2633b53fbb0b', 'shyamoli-paribahan', 'Shyamoli Paribahan (NR Travels)', 'শ্যামলী পরিবহন', 'intercity_bus', 'দেশব্যাপী আন্তঃজেলা ও আন্তর্জাতিক বাস সার্ভিস', 'Dhaka / Thanthania, Bogura', 'https://shyamoliparibahan.com.bd/', 'One of Bangladesh''s premier transport brands with extensive nationwide coverage. Operates frequent Volvo, Scania, and Hyundai AC coach trips from Bogura to Dhaka, Sylhet, Chittagong, and Cox''s Bazar.', '["Volvo & Scania multi-axle Air Conditioned fleet","Air-suspension smooth highway ride","Mineral water, blanket (night trip), entertainment system","Direct connecting service to international land borders (Benapole, Burimari)"]'::jsonb, '["Bogura – Dhaka (Mohakhali / Sayedabad / Arambagh)","Bogura – Chattogram – Cox''s Bazar","Bogura – Sylhet","Bogura – Khulna – Benapole"]'::jsonb, '[{"location":"Satmatha, Bogura","counter_name":"Satmatha Bus Counter","phone_numbers":["01712-900117","051-64920"]},{"location":"Thanthania Bus Stand, Bogura","counter_name":"Thanthania Bus Counter","phone_numbers":["01712-292660","051-64455"]}]'::jsonb, '+880 1712-900117', '["+880 1712-900117","+880 1712-292660","+880 51-64920","+880 51-64455"]'::jsonb, 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('75d0223b-9ec4-5cbd-ba7a-c8a4a6b41cb2', 'bogura-rent-a-car-services', 'Bogura Rent-A-Car & Microbus Association', 'বগুড়া রেন্ট-এ-কার ও মাইক্রোবাস সার্ভিস', 'rent_a_car', 'প্রাইভেট কার, মাইক্রোবাস ও পর্যটন বাহন ভাড়া', 'Thanthania Bus Stand / Charmatha / Satmatha, Bogura', 'https://rentacarbogurabangladesh.com/', 'Comprehensive fleet of air-conditioned private sedans (Noah, HiAce, Axio, Allion, Premio), wedding luxury cars, and 24/7 tourist vehicles for sightseeing trips across Bogura (Mahasthangarh, Behula Bashorghar, Kherua Mosque) and all over Bangladesh.', '["Toyota HiAce, Noah & Voxie microbuses (7–14 seaters)","Executive sedans (Axio, Premio, Allion) with professional chauffeurs","24-hour on-call airport pickup & drop (Bogura to Dhaka Airport)","Daily, weekly, and monthly corporate vehicle rental contracts","Archaeological sightseeing day-tour packages across Bogura district"]'::jsonb, '["Bogura City – Mahasthangarh – Shibganj Heritage Tour","Bogura – Dhaka Airport (Direct VIP drop)","Bogura – Rajshahi / Rangpur / Dinajpur","Local inter-upazila visits across all 12 upazilas of Bogura"]'::jsonb, '[{"location":"Opposite Thanthania Bus Terminal, Sherpur Road, Bogura","counter_name":"Thanthania Stand Counter","phone_numbers":["01725-141408","01935-660304"]},{"location":"Near Central Bus Terminal, Charmatha, Bogura","counter_name":"Charmatha Stand Counter","phone_numbers":["01727-965752","01712-503068"]}]'::jsonb, '+880 1725-141408', '["+880 1725-141408","+880 1935-660304","+880 1727-965752","+880 1712-503068"]'::jsonb, 'https://images.unsplash.com/photo-1549294413-26f195200c16?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41.574Z'),
  ('77442d9c-f630-584e-891a-01fb40695e92', 'shah-fateh-ali-paribahan', 'Shah Fateh Ali Paribahan', 'শাহ ফতেহ আলী পরিবহন', 'intercity_bus', 'আন্তঃজেলা বিলাসবহুল এসি ও নন-এসি বাস', 'Thanthania Bus Stand, Bogura', 'https://www.shohoz.com/bus-tickets', 'Bogura''s most iconic and reliable premium bus service, specializing in rapid and comfortable trips between Bogura and Dhaka. Offers Hyundai & Hino 1J AC coaches, sleeper services, and executive non-AC buses with departures every 20-30 minutes.', '["Hyundai Universe & Hino 1J Air-Conditioned coaches","Comfortable reclining seats with generous legroom","Complimentary drinking water & mobile charging ports","Dedicated VIP waiting lounges at Thanthania and Satmatha","GPS tracking & emergency highway breakdown support","Online ticket booking via Shohoz & bKash"]'::jsonb, '["Bogura – Dhaka (Mohakhali / Gabtoli / Abdullahpur / Panthapath)","Bogura – Chattogram","Bogura – Cox''s Bazar","Bogura – Sylhet"]'::jsonb, '[{"location":"Thanthania Bus Stand, Sherpur Road, Bogura","counter_name":"Thanthania Main Counter","phone_numbers":["01938-896457","01711-020626","051-67111"]},{"location":"Opposite Pouro Park / Satmatha, Bogura","counter_name":"Satmatha City Counter","phone_numbers":["01938-896456","051-61222"]},{"location":"Charmatha Central Bus Terminal, Bogura","counter_name":"Charmatha Terminal Counter","phone_numbers":["01938-896458"]},{"location":"Sherpur Bus Stand, Bogura","counter_name":"Sherpur Upazila Counter","phone_numbers":["01938-896474"]},{"location":"Dupchanchia Bus Stand, Bogura","counter_name":"Dupchanchia Counter","phone_numbers":["01938-896472"]},{"location":"Mahasthangarh Bus Stand, Shibganj, Bogura","counter_name":"Mahasthangarh Counter","phone_numbers":["01938-896483"]}]'::jsonb, '+880 1938-896457', '["+880 1938-896457","+880 1711-020626","+880 1938-896456","+880 51-67111","+880 51-61222"]'::jsonb, 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=1200&q=80', '2026-11-24T04:07:41